<template>
<v-app><v-navigation-drawer permanent width="220"><div class="brand"><v-icon color="primary" size="32">mdi-waves</v-icon><div>Disboard</div></div><v-list nav><v-list-item prepend-icon="mdi-view-dashboard-outline" title="监控工作台" :active="page==='work'" @click="navigate('work')"/><v-list-item prepend-icon="mdi-map-outline" title="长江口与杭州湾" :active="page==='region'" @click="navigate('region')"/><v-list-item prepend-icon="mdi-database-outline" title="检测记录" :active="page==='archive'" @click="navigate('archive')"/></v-list></v-navigation-drawer>
<v-app-bar flat border><v-app-bar-title>近海漂浮垃圾监测</v-app-bar-title><v-chip class="mr-6" color="primary" variant="tonal">上海近海研究区域</v-chip></v-app-bar>
<v-main><div class="workspace"><section :class="{'workspace-shell':page==='work'}">
<div v-if="page==='work'" class="workspace-toolbar"><v-tabs v-model="inputMode" color="primary" @update:model-value="switchMode"><v-tab value="image" :disabled="liveRunning">图片检测</v-tab><v-tab value="video" :disabled="liveRunning">录像接入</v-tab><v-tab value="live">连接无人机直播</v-tab></v-tabs><v-btn class="refresh-in-panel" prepend-icon="mdi-refresh" color="primary" variant="outlined" @click="load">刷新记录</v-btn></div>
<LiveConsole v-if="page==='work'&&inputMode==='live'" :active-monitoring-id="selected?.id" @select="select" @start="startLive" @sample="liveSample" @prediction="receivePrediction" @running="liveRunning=$event"/>
<v-alert v-if="error" type="error" closable class="mb-5" @click:close="error=''">{{error}}</v-alert><v-alert v-if="notice" type="success" closable class="mb-5" @click:close="notice=''">{{notice}}</v-alert>
<v-card v-if="page==='region'" rounded="xl" flat border class="mb-4"><v-card-title>导入候选点位</v-card-title><v-card-text><v-file-input label="选择点位 JSON 文件" accept=".json,application/json" v-model="sourceFile"/><v-btn :disabled="!sourceFile||busy" @click="importSources">导入点位</v-btn><v-btn variant="text" @click="downloadTemplate">下载导入模板</v-btn><p class="caption mt-2">每项填写名称、类型、经纬度、is_test；真实点位还需 source_url。导入后会在地图展示。</p></v-card-text></v-card>
<RegionView v-if="page==='region'" :candidates="candidates" :flow="flow" :records="records" :trace-result="traceResult" :active-record="selected" @updated="load"/>
<RecordLedger v-if="page==='archive'&&ledger" :key="ledger.id" :record="ledger" :detections="ledgerDetections" :traces="ledgerTraces" @close="ledger=null" @copy="copyRecord" :predicting="busy" @repredict="repredictRecord"/>
<v-card v-if="page==='archive'&&!ledger" rounded="xl" flat border><v-card-text><v-tabs v-model="archiveType" color="primary" class="mb-4"><v-tab value="IMAGE">图片检测</v-tab><v-tab value="VIDEO">录像分析</v-tab><v-tab value="STREAM">直播连接</v-tab></v-tabs><div class="ledger-tools"><v-text-field v-model="archiveSearch" prepend-inner-icon="mdi-magnify" label="搜索记录名称" variant="outlined" density="compact" hide-details/><v-chip color="primary">{{archiveRecords.length}} 条记录</v-chip></div><v-table hover><thead><tr><th>记录名称</th><th>{{archiveType==='STREAM'?'开始观测时间':'拍摄时间'}}</th><th>最新一帧目标</th><th>{{archiveType==='STREAM'?'采样帧数':'识别次数'}}</th><th>可能来源 / 进度</th><th>操作</th></tr></thead><tbody><tr v-for="r in archiveRecords" :key="r.id"><td class="record-name">{{r.title}}</td><td>{{dateText(r.captured_at)}}</td><td>{{r.last_count==null?'—':r.last_count+' 个'}}</td><td>{{r.frame_count||0}}</td><td class="conclusion-cell">{{r.last_conclusion||'尚未预测'}}</td><td><v-btn variant="text" color="primary" @click="openRecord(r)">查看详情</v-btn></td></tr></tbody></v-table><p v-if="!archiveRecords.length" class="empty">暂无{{typeNames[archiveType]}}记录</p></v-card-text></v-card>
<div v-show="page==='work'" class="grid"><v-card rounded="xl" flat border><v-card-title>{{inputMode==='image'?'图片素材':inputMode==='video'?'录像素材':'本次预测记录'}}</v-card-title><v-card-text v-if="inputMode!=='live'"><v-file-input :label="inputMode==='image'?'选择待检测图片':'选择录像文件'" :accept="inputMode==='image'?'image/*':'video/*'" v-model="file" variant="outlined" density="compact"/><div class="actions"><v-btn v-if="inputMode!=='live'" color="primary" :loading="busy" :disabled="!file" @click="upload">上传并建档</v-btn></div></v-card-text><v-divider/><v-list v-if="inputMode!=='live'" lines="two"><v-list-item v-for="r in workingRecords" :key="r.id" :active="selected?.id===r.id" @click="openRecord(r)" :title="r.title" :subtitle="dateText(r.captured_at||r.created_at)+' · '+(r.last_count==null?'尚未识别':r.last_count+' 个目标')" prepend-icon="mdi-video-outline"/><div v-if="!workingRecords.length" class="empty">暂无监控记录，上传图片或视频开始。</div></v-list><v-list v-else lines="three"><v-list-item v-for="(prediction,index) in livePredictions" :key="prediction.id" :title="prediction.result.conclusion||prediction.result.reason||'预测结果'" :subtitle="dateText(prediction.created_at)+' · 第 '+(livePredictions.length-index)+' 次预测'" @click="viewPrediction(prediction)"/><div v-if="!livePredictions.length" class="empty">暂无手动预测记录</div></v-list></v-card>
<div><v-card rounded="xl" flat border><v-card-title>观测与分析</v-card-title><v-tabs v-model="tab" color="primary" @update:model-value="changePane"><v-tab value="observe">观测信息</v-tab><v-tab value="detect" :disabled="!selected">目标识别</v-tab><v-tab value="trace" :disabled="!selected">来源预测</v-tab></v-tabs><v-divider/><v-card-text><section v-show="tab==='observe'"><template v-if="selected"><v-text-field :disabled="busy||liveRunning" label="记录名称" v-model="form.title" variant="outlined"/><v-text-field v-if="selected.media_type!=='STREAM'" :disabled="busy" label="拍摄时间（北京时间）" type="datetime-local" v-model="form.captured_at" variant="outlined"/><v-alert v-else type="info" variant="tonal" class="mb-4">直播截取使用服务器系统时间，无需手动填写。</v-alert><div class="actions mb-3"><v-btn v-if="!selecting" :disabled="busy||liveRunning" color="primary" variant="tonal" prepend-icon="mdi-selection-drag" @click="beginArea">选择区域</v-btn><template v-else><v-btn color="primary" :disabled="!draftBounds || drawing" @click="confirmArea">确定区域</v-btn><v-btn color="grey-darken-1" variant="outlined" @click="cancelArea">取消</v-btn></template></div><p class="caption mb-3" role="status">{{selecting?'按住鼠标拖拽框选，可重新拖拽调整；确认后更新范围，按 Esc 可取消。':'点击“选择区域”后拖拽框选；地图平时可正常拖动与缩放。'}}</p><div ref="mapEl" class="map" :class="{'area-selecting':selecting}"></div><div class="two mt-4"><v-text-field :readonly="selecting" :disabled="busy||liveRunning" label="经度范围" v-model="lon" hint="121.2,122.5" variant="outlined"/><v-text-field :readonly="selecting" :disabled="busy||liveRunning" label="纬度范围" v-model="lat" hint="30.5,31.6" variant="outlined"/></div><div class="actions-right"><v-btn size="small" color="grey-darken-1" variant="outlined" :disabled="busy||liveRunning" @click="openSettings">其他设置</v-btn><v-btn :disabled="selecting||busy||liveRunning" color="primary" @click="save">保存元数据</v-btn></div></template><div v-else class="empty">先上传素材或确认直播连接，填写本次观测信息</div></section><template v-if="selected"><div v-if="tab==='detect'"><div class="two"><v-text-field v-if="selected.media_type==='VIDEO'" v-model.number="seconds" type="number" min="0" label="视频取帧时间（秒）" variant="outlined"/><v-select v-model="model" :disabled="selected.media_type==='STREAM'" :items="['v4b','v4','v3']" label="识别模型" variant="outlined"/></div><v-btn v-if="selected.media_type!=='STREAM'" color="primary" :loading="busy" @click="detect">{{selected.media_type==='IMAGE'?'检测图片中的垃圾':'识别当前帧'}}</v-btn><p class="caption mt-3">按帧统计数量，不将重复出现的目标累加成垃圾总数。</p><div v-if="result" class="mt-5"><svg class="preview" :viewBox="`0 0 ${result.detection.image_size[0]} ${result.detection.image_size[1]}`"><image :href="result.image" width="100%" height="100%"/><g v-for="(d,i) in result.detection.detections" :key="i"><rect :x="d.bbox_xyxy[0]" :y="d.bbox_xyxy[1]" :width="d.bbox_xyxy[2]-d.bbox_xyxy[0]" :height="d.bbox_xyxy[3]-d.bbox_xyxy[1]" fill="none" stroke="#00d084" stroke-width="2"/><text :x="d.bbox_xyxy[0]" :y="Math.max(16,d.bbox_xyxy[1]-4)" fill="#00d084" font-size="14">{{d.class_cn}} {{Math.round(d.confidence*100)}}%</text></g></svg><div class="actions mt-3"><v-chip v-for="(count,type) in counts" :key="type" color="primary">{{type}} {{count}}</v-chip><v-chip>共 {{result.detection.num_detections}} 个目标</v-chip></div><v-btn v-if="selected.media_type!=='STREAM'" class="mt-4" color="primary" @click="tab='trace'">下一步：预测可能来源</v-btn></div></div>
<div v-if="tab==='trace'"><v-alert type="info" variant="tonal" class="mb-4">来源分析使用拍摄时间、观测区域与已下载历史流场。类别为辅助线索；结果展示轨迹与候选点的接近程度。</v-alert><v-list><v-list-item v-for="s in candidates" :key="s.id" :title="s.name+(s.metadata?.is_test?'【测试点】':'')" :subtitle="s.evidence"><template #append><a v-if="s.metadata.source_url" :href="s.metadata.source_url" target="_blank" rel="noopener">出处</a></template></v-list-item></v-list><p class="caption mb-4">这些点位用于候选排查，不表示已确认排污。养殖区暂无核实点位，不虚构标记。</p><v-alert class="mb-4" variant="tonal" :type="flow?.available?'info':'warning'">历史流场：{{flow?.available?flow.provider+' · '+new Date(flow.start*1000).toLocaleString()+' 至 '+new Date(flow.end*1000).toLocaleString():'下载中或尚不可用'}}</v-alert><p class="mb-3">自动按数量降序选择累计占比达到 70% 的主要类别。当前漂移模型各类共用流场，类别不直接决定来源。</p><v-text-field v-model.number="hours" label="回溯时长（小时）" type="number" min="1" max="168" variant="outlined"/><v-btn color="primary" :loading="busy" :disabled="selecting||busy||!result" @click="predict">{{traceResult?'重新预测':'保存观测信息并预测来源'}}</v-btn><div v-if="traceResult" class="mt-4"><v-alert :type="traceResult.status==='COMPLETED'?'success':'warning'" variant="tonal">{{traceResult.result.conclusion||traceResult.result.reason}}</v-alert><div class="actions mt-3"><v-chip v-for="c in traceResult.result.selected_classes||[]" :key="c.type">{{c.type}} · {{c.count}} 个 · {{Math.round(c.share*100)}}%</v-chip></div><p class="mt-3" v-if="traceResult.result.valid_particles!==undefined">有效粒子 {{traceResult.result.valid_particles}} / {{traceResult.result.released_particles}} · 完整回溯 {{traceResult.result.completed_particles}} · {{traceResult.result.flow?.provider}}</p><v-table v-if="traceResult.result.candidate_sources"><thead><tr><th>候选点</th><th>类型</th><th>5km 内经过粒子</th><th>最近距离</th></tr></thead><tbody><tr v-for="s in traceResult.result.candidate_sources" :key="s.id"><td>{{s.name}}</td><td>{{s.source_type}}</td><td>{{s.encounter_particles}}</td><td>{{s.closest_distance_km??'无有效轨迹'}} km</td></tr></tbody></v-table><p v-for="note in traceResult.result.limitations||[]" :key="note" class="caption mt-2">{{note}}</p></div></div>
</template></v-card-text></v-card></div></div></section></div></v-main><v-dialog v-model="settingsOpen" max-width="560"><v-card title="其他设置"><v-card-text><v-text-field v-model="draftDevice" label="无人机 / 设备编号" variant="outlined"/><v-textarea label="自定义元数据（JSON）" v-model="draftMetadata" rows="4" variant="outlined"/><v-checkbox v-if="selected?.media_type!=='STREAM'" v-model="draftTest" label="使用演示点位" hide-details/><p v-if="selected?.media_type!=='STREAM'" class="caption">演示点位是人为设置的测试位置，仅用于测试预测流程；关闭时只比较正式导入的候选点。</p></v-card-text><v-card-actions class="justify-end"><v-btn color="grey-darken-1" variant="outlined" @click="settingsOpen=false">取消</v-btn><v-btn color="primary" variant="flat" @click="applySettings">确定</v-btn></v-card-actions></v-card></v-dialog></v-app>
</template>
<script setup>
import {ref,computed,nextTick,onMounted,onBeforeUnmount} from 'vue'
import L from 'leaflet'
import RegionView from './views/RegionView.vue'
import LiveConsole from './components/LiveConsole.vue'
import RecordLedger from './components/RecordLedger.vue'
import {dateText,typeNames,statusNames} from './utils/display'
const page=ref('work')
async function navigate(value){cancelArea();page.value=value;await nextTick();if(value==='work'&&map)map.invalidateSize()}
async function openRecord(r){await run(async()=>{archiveType.value=r.media_type;ledger.value=await api('/records/'+r.id);ledgerDetections.value=await api('/records/'+r.id+'/detections');ledgerTraces.value=await api('/records/'+r.id+'/traces');await navigate('archive')})}
async function repredictRecord(d){if(!ledger.value||!d)return;await run(async()=>{await api('/records/'+ledger.value.id+'/repredict',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({detection_id:d.id})});ledgerTraces.value=await api('/records/'+ledger.value.id+'/traces');records.value=await api('/records');notice.value='已沿用这次识别结果重新预测，原有结果仍保留'})}
async function changePane(value){cancelArea();await nextTick();if(value==='observe'&&map)map.invalidateSize()}
async function copyRecord(r){await run(async()=>{const fresh=await api('/records/'+r.id+'/copy',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});ledger.value=null;inputMode.value=fresh.media_type==='IMAGE'?'image':'video';await navigate('work');await select(fresh);records.value=await api('/records');notice.value='已创建独立检测记录，历史结果保持只读'})}
const ledger=ref(null),ledgerDetections=ref([]),ledgerTraces=ref([]),settingsOpen=ref(false),draftMetadata=ref('{}'),draftDevice=ref(''),draftTest=ref(false),liveRunning=ref(false)
function openSettings(){draftMetadata.value=metadata.value;draftDevice.value=device.value;draftTest.value=includeTest.value;settingsOpen.value=true}
function applySettings(){try{JSON.parse(draftMetadata.value);metadata.value=draftMetadata.value;device.value=draftDevice.value;includeTest.value=draftTest.value;settingsOpen.value=false}catch{error.value='自定义元数据必须是有效 JSON'}}
function switchMode(){file.value=null;liveRunning.value=false;cancelArea();if(map){map.remove();map=null;document.removeEventListener('keydown',areaKey)}selected.value=null;result.value=null;traceResult.value=null;livePredictions.value=[]}

const livePredictions=ref([])
function receivePrediction(prediction){traceResult.value=prediction;if(selected.value?.media_type==='STREAM'){livePredictions.value=[{...prediction,created_at:prediction.created_at||new Date().toISOString()},...livePredictions.value.filter(p=>p.id!==prediction.id)]}}
function viewPrediction(prediction){traceResult.value=prediction;tab.value='trace'}
const sourceFile=ref(null),includeTest=ref(false)
const connection=ref(null),lanHost=ref('')
const rtmpAddress=computed(()=>connection.value&&lanHost.value?'rtmp://'+lanHost.value+':'+connection.value.rtmp_port+connection.value.path_prefix:'')
async function copyStream(){if(!rtmpAddress.value)return;try{await navigator.clipboard.writeText(rtmpAddress.value+connection.value.stream_key);notice.value='完整推流地址已复制'}catch{error.value='复制失败，请选中字段手动复制'}}
const flow=ref(null)
const hours=ref(24)
const inputMode=ref('image'),candidates=ref([]),archiveType=ref('IMAGE'),archiveSearch=ref('')
const workingRecords=computed(()=>records.value.filter(r=>r.media_type===({image:'IMAGE',video:'VIDEO',live:'STREAM'}[inputMode.value])))
const archiveRecords=computed(()=>records.value.filter(r=>r.media_type===archiveType.value&&r.title.toLowerCase().includes(archiveSearch.value.toLowerCase())))
const records=ref([]),selected=ref(null),form=ref({}),file=ref(null),error=ref(''),notice=ref(''),busy=ref(false),tab=ref('observe'),seconds=ref(0),model=ref('v4b'),result=ref(null),past=ref([]),garbage=ref('Plastic'),traceResult=ref(null),device=ref(''),metadata=ref('{}'),lon=ref('121.2,122.5'),lat=ref('30.5,31.6'),mapEl=ref(null)
const selecting=ref(false),drawing=ref(false),draftBounds=ref(null)
let map,rectangle,draftRectangle,dragStart,dragPoint,pointerId,interactionState
function beginArea(){
 if(!map)return
 selecting.value=true;draftBounds.value=null
 interactionState={};for(const key of ['dragging','boxZoom','doubleClickZoom','touchZoom','scrollWheelZoom']){interactionState[key]=map[key].enabled();map[key].disable()}
 map.closePopup()
}
function cancelArea(){
 selecting.value=false;drawing.value=false;draftBounds.value=null;dragStart=null
 if(draftRectangle){draftRectangle.remove();draftRectangle=null}
 if(map&&interactionState){for(const [key,enabled] of Object.entries(interactionState))if(enabled)map[key].enable();interactionState=null}
 if(pointerId!==undefined&&mapEl.value?.hasPointerCapture(pointerId))mapEl.value.releasePointerCapture(pointerId)
 pointerId=undefined
}
function confirmArea(){
 if(!draftBounds.value||drawing.value)return
 const b=draftBounds.value
 lon.value=[b.getWest(),b.getEast()].map(v=>v.toFixed(6)).join(',')
 lat.value=[b.getSouth(),b.getNorth()].map(v=>v.toFixed(6)).join(',')
 cancelArea();draw();notice.value='区域已确定，点击“保存元数据”保存到当前记录'
}
function areaDown(e){
 if(!selecting.value||e.button!==0||drawing.value)return
 e.preventDefault();e.stopPropagation();pointerId=e.pointerId;mapEl.value.setPointerCapture(pointerId)
 dragStart=map.mouseEventToLatLng(e);dragPoint=[e.clientX,e.clientY];drawing.value=true;draftBounds.value=null
 if(draftRectangle){draftRectangle.remove();draftRectangle=null}
}
function areaMove(e){
 if(!drawing.value||e.pointerId!==pointerId)return
 e.preventDefault();const end=map.mouseEventToLatLng(e)
 const b=L.latLngBounds(dragStart,end)
 if(!draftRectangle)draftRectangle=L.rectangle(b,{color:'#e8710a',weight:2,dashArray:'6 4',fillOpacity:.15,interactive:false}).addTo(map)
 else draftRectangle.setBounds(b)
}
function areaUp(e){
 if(!drawing.value||e.pointerId!==pointerId)return
 areaMove(e);drawing.value=false
 const b=draftRectangle?.getBounds()
 if(b&&Math.abs(e.clientX-dragPoint[0])>=8&&Math.abs(e.clientY-dragPoint[1])>=8&&b.getSouth()>=-90&&b.getNorth()<=90&&b.getWest()>=-180&&b.getEast()<=180)draftBounds.value=b
 else{draftRectangle?.remove();draftRectangle=null;draftBounds.value=null}
 if(mapEl.value.hasPointerCapture(pointerId))mapEl.value.releasePointerCapture(pointerId)
 pointerId=undefined
}
function areaKey(e){if(e.key==='Escape'&&selecting.value)cancelArea()}
function bindArea(){const el=mapEl.value;el.addEventListener('pointerdown',areaDown);el.addEventListener('pointermove',areaMove);el.addEventListener('pointerup',areaUp);el.addEventListener('pointercancel',cancelArea);document.addEventListener('keydown',areaKey)}
onBeforeUnmount(()=>{cancelArea();document.removeEventListener('keydown',areaKey);map?.remove()})
const counts=computed(()=>{const out={};for(const d of result.value?.detection.detections||[])out[d.class_cn]=(out[d.class_cn]||0)+1;return out})
async function api(path,options={}){const r=await fetch('/api'+path,options);const data=await r.json();if(!r.ok)throw new Error(data.detail||data.message||'请求失败');return data}
async function run(fn){error.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){await run(async()=>{records.value=await api('/records');candidates.value=await api('/candidate-sources');flow.value=await api('/currents')})}
function draw(){if(rectangle)rectangle.remove();const x=lon.value.split(',').map(Number),y=lat.value.split(',').map(Number);rectangle=L.rectangle([[y[0],x[0]],[y[1],x[1]]],{color:'#1a73e8',weight:2,interactive:false}).addTo(map);map.fitBounds(rectangle.getBounds())}
async function select(r){if(selected.value?.id!==r.id)livePredictions.value=[];tab.value='observe';connection.value=null;cancelArea();selected.value=r;form.value={...r};form.value.captured_at=(r.captured_at||'').slice(0,16);metadata.value=JSON.stringify(r.metadata||{},null,2);device.value=r.metadata?.device_id||'';const a=r.observation_area;lon.value=a?`${a.west},${a.east}`:'121.2,122.5';lat.value=a?`${a.south},${a.north}`:'30.5,31.6';result.value=null;traceResult.value=null;if(trackLayer)trackLayer.remove();await nextTick();if(!map){map=L.map(mapEl.value).setView([31,121.8],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);bindArea()}draw();showSources();if(r.media_type==='STREAM'){connection.value=await api('/videos/streams/'+r.id+'/connection');lanHost.value=connection.value.hosts[0]?.address||''}const old=await api('/records/'+r.id+'/traces');if(old.length)traceResult.value=old[0];if(r.media_type==='STREAM')livePredictions.value=old}
let sourceLayer
function showSources(){if(sourceLayer)sourceLayer.remove();sourceLayer=L.layerGroup().addTo(map);for(const s of candidates.value){const el=document.createElement('div');el.textContent=s.name+(s.metadata?.is_test?'【测试点】':'');L.circleMarker([s.latitude,s.longitude],{color:s.metadata?.status==='CONFIRMED_POLLUTION'?'#d93025':s.metadata?.status==='CLEARED'?'#188038':'#f9ab00',radius:7}).bindTooltip(el).addTo(sourceLayer)}}
async function upload(){await run(async()=>{const fd=new FormData();fd.append('file',Array.isArray(file.value)?file.value[0]:file.value);const r=await api('/videos/upload',{method:'POST',body:fd});records.value=await api('/records');await select(r);notice.value='已接收，尚未执行识别'})}
async function stream(){await run(async()=>{const r=await api('/videos/streams',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:'无人机直播'})});records.value=await api('/records');await select(r.record);notice.value='直播接收已准备好，请按右侧两个字段填写 DJI 设置'})}
async function save(){await run(async()=>{const x=lon.value.split(',').map(Number),y=lat.value.split(',').map(Number);if(x.length!==2||y.length!==2||![...x,...y].every(Number.isFinite)||x[0]>=x[1]||y[0]>=y[1]||x[0]<-180||x[1]>180||y[0]<-90||y[1]>90)throw new Error('请填写有效的经纬度范围');const body={title:form.value.title,captured_at:selected.value.media_type==='STREAM'?null:(form.value.captured_at?form.value.captured_at.replace('T',' ')+':00':null),observation_area:{west:x[0],east:x[1],south:y[0],north:y[1]},metadata:{...JSON.parse(metadata.value),device_id:device.value}};selected.value=await api('/records/'+selected.value.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});draw();notice.value='元数据已保存'})}
async function detect(){await run(async()=>result.value=await api('/detections',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({monitoring_id:selected.value.id,frame_seconds:seconds.value,model:model.value})}))}
let trackLayer
async function trace(){await run(async()=>{traceResult.value=await api('/traces',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({monitoring_id:selected.value.id,garbage_type:garbage.value,hours:hours.value,include_test:includeTest.value,...(result.value?.id?{detection_id:result.value.id}:{})})});if(trackLayer)trackLayer.remove();trackLayer=L.featureGroup().addTo(map);for(const tr of traceResult.value.result.tracks||[]){if(tr.length>1)L.polyline(tr.map(p=>[p[1],p[0]]),{color:'#0b8060',weight:1.5,opacity:.6}).addTo(trackLayer)}if(trackLayer.getLayers().length)map.fitBounds(trackLayer.getBounds(),{padding:[20,20]})})}
async function startLive(s){if(selected.value?.id!==s.monitoring_id){error.value='请先点击该直播连接，选择它的观测记录';return}await save();if(error.value)return;await run(async()=>{await api('/live/sessions/'+s.id+'/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:s.mode})});notice.value='本次连接已开始监控'})}
function liveSample(sample){if(sample.detection.monitoring_id!==selected.value?.id)return;result.value=sample.detection;}
async function predict(){if(selecting.value||!result.value)return;if(selected.value.media_type==='STREAM'){await run(async()=>{traceResult.value=await api('/records/'+selected.value.id+'/repredict',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({detection_id:result.value.id})});receivePrediction(traceResult.value)});return}await save();if(!error.value)await trace()}
async function importSources(){await run(async()=>{const f=Array.isArray(sourceFile.value)?sourceFile.value[0]:sourceFile.value;const data=JSON.parse(await f.text());if(!Array.isArray(data))throw new Error('JSON 顶层必须是点位数组');const r=await api('/candidate-sources/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});candidates.value=await api('/candidate-sources');notice.value=`已导入 ${r.imported} 个候选点位`})}
function downloadTemplate(){const data=[{name:'示例测试点',source_type:'排水口',longitude:122.1,latitude:31.1,is_test:true,source_url:'',coordinate_datum:'WGS84',evidence:'合成测试点'}];const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='candidate-sources.json';a.click();URL.revokeObjectURL(url)}
async function history(){await run(async()=>past.value=await api('/records/'+selected.value.id+'/detections'))}
onMounted(load)
</script>
<style>
body{font-family:Arial,'Microsoft YaHei',sans-serif;color:#202124}.brand{display:flex;gap:12px;align-items:center;padding:22px 18px;font-size:21px;font-weight:600}.brand small{display:block;font-size:9px;letter-spacing:1.4px;color:#80868b;margin-top:5px}.drawer-note{padding:24px;color:#80868b;font-size:12px;line-height:2}.workspace-toolbar{display:flex;align-items:center;gap:16px;border-bottom:1px solid #e5e7eb;margin-bottom:16px;padding-bottom:8px}.workspace-toolbar .v-tabs{flex:1;min-width:0}.refresh-in-panel{flex-shrink:0}@media(max-width:700px){.workspace-toolbar{flex-wrap:wrap}.workspace-toolbar .v-tabs{flex-basis:100%}.refresh-in-panel{margin-left:auto}}.workspace-shell{background:#fff;border:1px solid #dce2e9;border-radius:10px;padding:16px;min-height:calc(100vh - 160px)}.workspace{width:100%;max-width:none;padding:22px 24px;margin:0}.heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px;gap:16px}.eyebrow{font-size:11px;letter-spacing:2px;color:#1a73e8;margin-bottom:10px}h1{font-size:26px;font-weight:500;letter-spacing:-1px}.heading p{color:#6b7280;margin-top:6px;font-size:14px}.grid{display:grid;grid-template-columns:310px minmax(0,1fr);gap:18px;align-items:start}.two{display:grid;grid-template-columns:1fr 1fr;gap:16px}.ledger-tools{display:flex;align-items:center;gap:16px;margin-bottom:20px}.record-name{font-weight:600;max-width:260px;overflow-wrap:anywhere}.conclusion-cell{max-width:340px;line-height:1.5;padding-top:12px!important;padding-bottom:12px!important}.actions-right{display:flex;justify-content:flex-end;align-items:center;gap:10px;margin-top:16px}.actions{display:flex;gap:10px;flex-wrap:wrap}.empty{padding:32px;color:#80868b;text-align:center}.area-selecting{cursor:crosshair!important;touch-action:none}.area-selecting .leaflet-interactive{pointer-events:none}.map{position:relative;overflow:hidden;isolation:isolate;height:260px;border-radius:14px;z-index:0}.preview{width:100%;max-height:440px;object-fit:contain;background:#f3f5f7;border-radius:12px}.caption{font-size:12px;color:#6b7280}.v-card-title{padding:18px 20px 8px!important;font-size:18px!important}.v-card-text{padding:16px 20px!important}@media(max-width:1100px){.grid{grid-template-columns:1fr}.workspace{padding:20px}.two{grid-template-columns:1fr}}
</style>
